.form-field {
  display: flex;
  flex-direction: column;
  gap: .625rem;
}

.form-field .question-number {
  font-size: .6875rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.form-field .question-label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.4;
}

.form-field .help-text {
  font-size: .8125rem;
  color: var(--color-text-help);
  display: flex;
  align-items: center;
  gap: .35rem;
}

.help-text svg {
  flex-shrink: 0;
  color: var(--color-text-help);
}

/* ── Options list ── */
.options-group {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  margin-top: .25rem;
}

/* ── Custom checkbox option ── */
.option-label {
  display: flex;
  align-items: center;
  gap: .875rem;
  padding: .75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition), box-shadow var(--transition);
  user-select: none;
  -webkit-user-select: none;
  position: relative;
}

.option-label:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.option-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

/* Focus-visible ring on label (driven by :has) */
.option-label:has(input[type="checkbox"]:focus-visible) {
  outline: none;
  box-shadow: var(--shadow-focus);
  border-color: var(--color-accent);
}

/* Custom checkbox box */
.checkbox-box {
  width: 1.125rem;
  height: 1.125rem;
  flex-shrink: 0;
  border: 1.5px solid var(--color-border);
  border-radius: 4px;
  background: var(--color-surface);
  display: grid;
  place-items: center;
  transition: background var(--transition), border-color var(--transition);
}

.checkbox-box svg {
  opacity: 0;
  transform: scale(.6);
  transition: opacity var(--transition), transform var(--transition);
  color: #fff;
}

.option-label:has(input[type="checkbox"]:checked) {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.option-label:has(input[type="checkbox"]:checked) .checkbox-box {
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.option-label:has(input[type="checkbox"]:checked) .checkbox-box svg {
  opacity: 1;
  transform: scale(1);
}

.option-text {
  font-size: .9375rem;
  color: var(--color-text-primary);
  line-height: 1.4;
}

/* ── Result state overlays on options ── */
