  background: var(--color-success-light);
}

.form-field.revealed .option-label.correct .checkbox-box {
  background: var(--color-success);
  border-color: var(--color-success);
}

.form-field.revealed .option-label.correct .checkbox-box svg {
  opacity: 1;
  transform: scale(1);
}

.form-field.revealed .option-label.wrong {
  border-color: var(--color-error);
  background: var(--color-error-light);
}

.form-field.revealed .option-label.wrong .checkbox-box {
  background: var(--color-error);
  border-color: var(--color-error);
}

.form-field.revealed .option-label.wrong .checkbox-box svg {
  opacity: 1;
  transform: scale(1);
}

/* ── Submit button ── */
.quiz-footer {
  padding: 1.25rem 1.5rem 1.75rem;
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.selection-hint {
  font-size: .8125rem;
  color: var(--color-text-help);
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  padding: .6875rem 1.5rem;
  font-size: .9375rem;
  font-weight: 600;
  color: #fff;
  background: var(--color-accent);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: -.01em;
}

.btn-submit:hover:not(:disabled) {
  background: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(99,102,241,.35);
}

.btn-submit:active:not(:disabled) {
  transform: translateY(0);
  box-shadow: none;
}

.btn-submit:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

.btn-submit:disabled {
  opacity: .55;
  cursor: not-allowed;
}

/* ── Score banner ── */
.score-banner {
  display: none;
  margin: 0 1.5rem 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .9375rem;
  font-weight: 500;
  align-items: center;
  gap: .75rem;
  animation: fadeUp .3s ease both;
}

.score-banner.show {
  display: flex;
}

.score-banner.perfect {
  background: var(--color-success-light);
  color: #065f46;
  border: 1px solid #6ee7b7;
}

.score-banner.good {
  background: #fffbeb;
  color: #92400e;
  border: 1px solid #fcd34d;
}

.score-banner.low {
  background: var(--color-error-light);
  color: #991b1b;
  border: 1px solid #fca5a5;
}

.score-banner .score-icon {
  font-size: 1.375rem;
  flex-shrink: 0;
}

.score-banner .score-text strong {
  display: block;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: .125rem;
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Dividers between questions ── */
.form-field + .form-field {
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}

/* ── Reflow at 320px ── */
@media (max-width: 480px) {
  .quiz-footer {
    flex-direction: column;
    align-items: stretch;
  }
  .btn-submit {
    justify-content: center;
  }
}
