+    heading = `${correct} out of ${total} correct`;
+    body = "Good effort — review the highlighted answers to learn more.";
+  } else {
+    cls = "low";
+    icon = "📖";
+    heading = `${correct} out of ${total} correct`;
+    body = "Keep studying — review the highlighted answers below.";
+  }
+
+  banner.className = `score-banner ${cls} show`;
+  banner.setAttribute("role", "status");
+  banner.setAttribute("aria-live", "polite");
+  banner.innerHTML = `
+    <span class="score-icon" aria-hidden="true">${icon}</span>
+    <span class="score-text">
+      <strong>${heading}</strong>
+      ${body}
+    </span>
+  `;
+}
+
+// ── Helpers ──────────────────────────────────────────────────────────────────
+function totalSelected() {
+  return QUESTIONS.reduce(
+    (acc, q) => acc + state.selections[q.id].size,
+    0
+  );
+}
+
+function updateProgress() {
+  const answered = QUESTIONS.filter((q) => state.selections[q.id].size > 0).length;
+  const pct = Math.round((answered / QUESTIONS.length) * 100);
+  document.getElementById("progress-fill").style.width = `${pct}%`;
+  document.getElementById("progress-answered").textContent = answered;
+}
+
+function updateSubmitButton() {
+  const btn = document.getElementById("btn-submit");
+  const anySelected = totalSelected() > 0;
+  btn.disabled = !anySelected;
+}
+
+// ── Submit handler ───────────────────────────────────────────────────────────
+function handleSubmit(e) {
+  e.preventDefault();
+  if (state.submitted) return;
+  state.submitted = true;
+
+  // Disable all checkboxes
+  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
+    cb.disabled = true;
+  });
+
+  // Reveal correct / wrong on each question
+  let totalCorrect = 0;
+  QUESTIONS.forEach((question) => {
+    const fieldEl = document.getElementById(`field-${question.id}`);
+    fieldEl.classList.add("revealed");
+
+    const selected = state.selections[question.id];
+    const correct = new Set(question.correctIds);
+
+    // Check if this entire question was answered correctly
+    const isQuestionCorrect =
+      selected.size === correct.size &&
+      [...selected].every((id) => correct.has(id));
+
+    if (isQuestionCorrect) totalCorrect++;
+
+    question.options.forEach((opt) => {
+      const label = document.querySelector(`label[for="${opt.id}"]`);
+      const isCorrect = correct.has(opt.id);
+      const isSelected = selected.has(opt.id);
+
+      if (isCorrect) {
+        // Always highlight correct answers green
+        label.classList.add("correct");
+        // Ensure the box shows the check mark even if not selected
+        const box = label.querySelector(".checkbox-box");
+        box.innerHTML = checkIcon();
+      } else if (isSelected && !isCorrect) {
+        // Incorrectly selected
+        label.classList.add("wrong");
+        const box = label.querySelector(".checkbox-box");
+        // Replace check with X for wrong selections
+        box.innerHTML = `<svg width="10" height="10" viewBox="0 0 10 10" fill="none" aria-hidden="true" focusable="false">
+          <path d="M1 1L9 9M9 1L1 9" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
+        </svg>`;
+      }
+    });
+  });
+
+  // Show score
+  ScoreBannerComponent(totalCorrect, QUESTIONS.length);
+
+  // Update button
+  const btn = document.getElementById("btn-submit");
+  btn.textContent = "Submitted";
+  btn.disabled = true;
+
+  // Move focus to score banner for screen readers
+  const banner = document.getElementById("score-banner");
+  banner.setAttribute("tabindex", "-1");
+  banner.focus();
+}
+
+// ── Mount ────────────────────────────────────────────────────────────────────
+function mount() {
+  const form = document.getElementById("quiz-form");
+
+  QUESTIONS.forEach((question, index) => {
+    form.appendChild(FormFieldComponent(question, index));
+  });
+
+  form.addEventListener("submit", handleSubmit);
+
+  updateProgress();
+  updateSubmitButton();
+}
+
+document.addEventListener("DOMContentLoaded", mount);
+
')

